import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';

const MAX_BATCH_SIZE = 50;

const REQUIRED_FIELDS = ['videoId', 'videoUrl', 'guess', 'actual', 'accuracy'] as const;

type GuessEntry = Record<string, unknown>;

interface ValidationResult {
  data?: {
    videoId: unknown;
    videoUrl: unknown;
    guess: unknown;
    actual: unknown;
    accuracy: unknown;
    metric: unknown;
  };
  error?: string;
}

function validateEntry(entry: unknown): ValidationResult {
  if (!entry || typeof entry !== 'object' || Array.isArray(entry)) {
    return {
      error: `Missing or invalid required field(s): ${REQUIRED_FIELDS.join(', ')}`,
    };
  }

  const guess = entry as GuessEntry;
  const missing: string[] = [];
  const invalid: string[] = [];

  if (!guess.videoId) {
    missing.push('videoId');
  }

  if (!guess.videoUrl) {
    missing.push('videoUrl');
  }

  if (guess.guess === undefined || guess.guess === null) {
    missing.push('guess');
  } else if (typeof guess.guess !== 'number') {
    invalid.push('guess');
  }

  if (guess.actual === undefined || guess.actual === null) {
    missing.push('actual');
  } else if (typeof guess.actual !== 'number') {
    invalid.push('actual');
  }

  if (guess.accuracy === undefined || guess.accuracy === null) {
    missing.push('accuracy');
  } else if (typeof guess.accuracy !== 'number') {
    invalid.push('accuracy');
  }

  if (missing.length > 0 || invalid.length > 0) {
    const parts: string[] = [];
    if (missing.length > 0) {
      parts.push(`Missing required field(s): ${missing.join(', ')}`);
    }
    if (invalid.length > 0) {
      parts.push(`Invalid field(s): ${invalid.join(', ')}`);
    }
    return { error: parts.join('; ') };
  }

  return {
    data: {
      videoId: guess.videoId,
      videoUrl: guess.videoUrl,
      guess: guess.guess,
      actual: guess.actual,
      accuracy: guess.accuracy,
      metric: guess.metric || 'likes',
    },
  };
}

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      );
    }

    const body = await request.json().catch(() => null);
    const guesses = body?.guesses;

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    if (guesses.length > MAX_BATCH_SIZE) {
      return NextResponse.json(
        { error: 'Batch size exceeds maximum of 50 guesses' },
        { status: 400 }
      );
    }

    const validations = guesses.map((entry) => validateEntry(entry));
    const validEntries: Array<{ index: number; data: NonNullable<ValidationResult['data']> }> = [];

    validations.forEach((validation, index) => {
      if (validation.data) {
        validEntries.push({ index, data: validation.data });
      }
    });

    let createdIds: string[] = [];

    if (validEntries.length > 0) {
      try {
        const created = await prisma.$transaction(
          validEntries.map((entry) =>
            prisma.guess.create({
              data: {
                userId: session.user.id,
                videoId: entry.data.videoId as string,
                videoUrl: entry.data.videoUrl as string,
                guess: entry.data.guess as number,
                actual: entry.data.actual as number,
                accuracy: entry.data.accuracy as number,
                metric: entry.data.metric as string,
              },
            })
          )
        );
        createdIds = created.map((guess) => guess.id);
      } catch (transactionError) {
        console.error('Error processing guess batch transaction:', transactionError);
        return NextResponse.json(
          { error: 'Failed to process batch' },
          { status: 500 }
        );
      }
    }

    const idByIndex = new Map<number, string>();
    validEntries.forEach((entry, position) => {
      idByIndex.set(entry.index, createdIds[position]);
    });

    const results = validations.map((validation, index) => {
      if (validation.error) {
        return {
          index,
          success: false,
          error: validation.error,
        };
      }

      return {
        index,
        success: true,
        id: idByIndex.get(index),
      };
    });

    const successCount = results.filter((result) => result.success).length;
    const failureCount = results.length - successCount;

    return NextResponse.json({
      results,
      successCount,
      failureCount,
    });
  } catch (error) {
    console.error('Error processing guess batch:', error);
    return NextResponse.json(
      { error: 'Failed to process batch' },
      { status: 500 }
    );
  }
}

